-- 0001_init: Postgres-зеркало итоговой схемы MySQL старого Zafiro (Laravel) после всех 86 миграций
-- из ../Zafiro/database/migrations. Подробная инвентаризация: docs/parts/30-database.md,
-- отличия и правила маппинга типов: docs/schema-changes.md.
--
-- Правила (не менять без обновления docs/schema-changes.md):
--  * имена таблиц, полей, индексов и ограничений — как в Laravel (для сверки и переноса данных);
--  * id — bigint GENERATED BY DEFAULT AS IDENTITY (старые id вставляются как есть, после переноса — setval);
--  * деньги — bigint в тиынах. В MySQL суммы хранились в decimal(12,2)/decimal(14,2) В ТЕНГЕ;
--    при переносе значение умножается на 100 (точно, без округления). Поля *_cents уже были в тиынах;
--  * время — timestamptz (MySQL timestamp/datetime хранили UTC: config/app.php timezone = UTC);
--  * json — jsonb; enum-строки — varchar + CHECK; unsigned — CHECK (>= 0) и тип на ступень шире;
--  * таблицы Laravel-инфраструктуры (sessions, cache, jobs, personal_access_tokens, …) не переносятся.
--  * Новое (ledger, аудит, RLS, партиции) здесь НЕ добавляется — только отдельными миграциями Этапа 1.

-- +goose Up

-- ---------------------------------------------------------------------------
-- Пользователи и клубы (тенанты)
-- ---------------------------------------------------------------------------

-- 0001_01_01_000000_create_users_table, 2026_10_09_000000 (колонки удалены в 2026_10_13_040140),
-- 2026_10_15_000000_add_is_superadmin, 2026_10_15_100000_create_superadmin_cabinet,
-- telegram-колонки добавлены в 2026_10_16_120000 и удалены в 2026_10_18_120000.
CREATE TABLE users (
    id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name              varchar(255) NOT NULL,
    phone             varchar(255) NOT NULL,
    email             varchar(255),
    email_verified_at timestamptz,
    password          varchar(255) NOT NULL,
    remember_token    varchar(100),
    created_at        timestamptz,
    updated_at        timestamptz,
    is_superadmin     boolean NOT NULL DEFAULT false,
    blocked_at        timestamptz,
    CONSTRAINT users_phone_unique UNIQUE (phone)
);

-- 2026_10_13_040135_create_clubs_table + installation_key (043934, 044406), locale (181908),
-- timezone (060000), agent_exit_pin (180000), logo_path (210000), agent_staff_minutes (220000),
-- signin_image_path (2026_10_19_120000).
CREATE TABLE clubs (
    id                        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name                      varchar(255) NOT NULL,
    slug                      varchar(255) NOT NULL,
    settings                  jsonb,
    created_at                timestamptz,
    updated_at                timestamptz,
    installation_key_hash     varchar(64),
    installation_key_prefix   varchar(12),
    installation_key          text,
    locale                    varchar(16),
    timezone                  varchar(64) NOT NULL DEFAULT 'Asia/Almaty',
    agent_exit_pin_hash       varchar(255),
    agent_exit_pin_changed_at timestamptz,
    agent_staff_minutes       integer NOT NULL DEFAULT 15 CHECK (agent_staff_minutes >= 0),
    logo_path                 varchar(255),
    signin_image_path         varchar(255),
    CONSTRAINT clubs_slug_unique UNIQUE (slug),
    CONSTRAINT clubs_installation_key_hash_unique UNIQUE (installation_key_hash)
);
CREATE INDEX clubs_installation_key_prefix_index ON clubs (installation_key_prefix);
COMMENT ON COLUMN clubs.installation_key IS 'В Laravel зашифрован Crypt (APP_KEY); формат в Go решается в Этапе 1, см. docs/open-questions/database.md';

-- 2026_10_13_042813_create_saas_plans_table
CREATE TABLE saas_plans (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug          varchar(80) NOT NULL,
    name          varchar(120) NOT NULL,
    price_monthly bigint,
    trial_days    integer NOT NULL DEFAULT 0 CHECK (trial_days >= 0),
    features      jsonb,
    is_active     boolean NOT NULL DEFAULT true,
    created_at    timestamptz,
    updated_at    timestamptz,
    CONSTRAINT saas_plans_slug_unique UNIQUE (slug)
);
CREATE INDEX saas_plans_is_active_index ON saas_plans (is_active);
COMMENT ON COLUMN saas_plans.price_monthly IS 'Тиыны (в MySQL decimal(12,2) в тенге)';

-- 2026_10_13_042814_create_club_subscriptions_table
CREATE TABLE club_subscriptions (
    id                     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id                bigint NOT NULL,
    saas_plan_id           bigint NOT NULL,
    status                 varchar(30) NOT NULL,
    started_at             timestamptz NOT NULL,
    trial_ends_at          timestamptz,
    current_period_ends_at timestamptz,
    canceled_at            timestamptz,
    provider               varchar(40),
    provider_reference     varchar(255),
    created_at             timestamptz,
    updated_at             timestamptz,
    CONSTRAINT club_subscriptions_club_id_unique UNIQUE (club_id),
    CONSTRAINT club_subscriptions_status_check CHECK (status IN ('trialing', 'active', 'expired', 'suspended')),
    CONSTRAINT club_subscriptions_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT club_subscriptions_saas_plan_id_foreign FOREIGN KEY (saas_plan_id) REFERENCES saas_plans (id) ON DELETE RESTRICT
);
CREATE INDEX club_subscriptions_status_index ON club_subscriptions (status);
CREATE INDEX club_subscriptions_saas_plan_id_foreign ON club_subscriptions (saas_plan_id);

-- 2026_10_13_040136_create_club_memberships_table + notifications_seen_at (173104),
-- can_manage_integrations (190912), total_spent (2026_10_15_000020), permissions (2026_10_30_100000).
CREATE TABLE club_memberships (
    id                      bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id                 bigint NOT NULL,
    user_id                 bigint NOT NULL,
    role                    varchar(255) NOT NULL DEFAULT 'Пользователь',
    permissions             jsonb,
    discount                numeric(5, 2) NOT NULL DEFAULT 0,
    total_spent             bigint NOT NULL DEFAULT 0,
    created_at              timestamptz,
    updated_at              timestamptz,
    notifications_seen_at   timestamptz,
    can_manage_integrations boolean NOT NULL DEFAULT false,
    CONSTRAINT club_memberships_club_id_user_id_unique UNIQUE (club_id, user_id),
    CONSTRAINT club_memberships_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT club_memberships_user_id_foreign FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE INDEX club_memberships_user_id_foreign ON club_memberships (user_id);
COMMENT ON COLUMN club_memberships.discount IS 'Персональная скидка, проценты (не деньги)';
COMMENT ON COLUMN club_memberships.total_spent IS 'Тиыны (в MySQL decimal(12,2) в тенге)';
COMMENT ON COLUMN club_memberships.role IS 'owner/admin/manager/cashier/operator/client и старые не-staff роли (например «Пользователь»), без CHECK';

-- 2026_10_13_040137_create_member_balances_table
CREATE TABLE member_balances (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id       bigint NOT NULL,
    user_id       bigint NOT NULL,
    balance       bigint NOT NULL DEFAULT 0,
    bonus_balance bigint NOT NULL DEFAULT 0,
    created_at    timestamptz,
    updated_at    timestamptz,
    CONSTRAINT member_balances_club_id_user_id_unique UNIQUE (club_id, user_id),
    CONSTRAINT member_balances_membership_fk FOREIGN KEY (club_id, user_id)
        REFERENCES club_memberships (club_id, user_id) ON DELETE CASCADE
);
COMMENT ON COLUMN member_balances.balance IS 'Тиыны (в MySQL decimal(12,2) в тенге)';
COMMENT ON COLUMN member_balances.bonus_balance IS 'Тиыны (в MySQL decimal(12,2) в тенге)';

-- 2026_10_13_042618_create_club_invitations_table
CREATE TABLE club_invitations (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id     bigint NOT NULL,
    email       varchar(255),
    role        varchar(40) NOT NULL,
    token_hash  varchar(64) NOT NULL,
    invited_by  bigint,
    expires_at  timestamptz NOT NULL,
    accepted_at timestamptz,
    created_at  timestamptz,
    updated_at  timestamptz,
    CONSTRAINT club_invitations_token_hash_unique UNIQUE (token_hash),
    CONSTRAINT club_invitations_role_check CHECK (role IN ('admin', 'manager', 'cashier', 'operator')),
    CONSTRAINT club_invitations_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT club_invitations_invited_by_foreign FOREIGN KEY (invited_by) REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX club_invitations_club_id_accepted_at_expires_at_index ON club_invitations (club_id, accepted_at, expires_at);
CREATE INDEX club_invitations_invited_by_foreign ON club_invitations (invited_by);

