-- 2026_08_08_172640_create_product_categories_table (+ club_id в 2026_10_13_040138..040140)
CREATE TABLE product_categories (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       varchar(255) NOT NULL,
    created_at timestamptz,
    updated_at timestamptz,
    club_id    bigint NOT NULL,
    CONSTRAINT product_categories_club_id_name_unique UNIQUE (club_id, name),
    CONSTRAINT product_categories_club_id_id_unique UNIQUE (club_id, id),
    CONSTRAINT product_categories_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE
);
CREATE INDEX product_categories_club_id_index ON product_categories (club_id);

-- 2026_08_08_065211_create_products_table, product_category_id (172641), club_id (040138..040140),
-- составной FK (042959), индекс (125224), deleted_at (2026_11_01_100000).
CREATE TABLE products (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sku                 varchar(255) NOT NULL,
    name                varchar(255) NOT NULL,
    category            varchar(255) NOT NULL,
    product_category_id bigint,
    price               bigint NOT NULL,
    quantity            bigint NOT NULL DEFAULT 0 CHECK (quantity >= 0),
    created_at          timestamptz,
    updated_at          timestamptz,
    club_id             bigint NOT NULL,
    deleted_at          timestamptz,
    CONSTRAINT products_club_id_sku_unique UNIQUE (club_id, sku),
    CONSTRAINT products_club_id_id_unique UNIQUE (club_id, id),
    CONSTRAINT products_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT products_club_category_fk FOREIGN KEY (club_id, product_category_id)
        REFERENCES product_categories (club_id, id) ON DELETE RESTRICT
);
CREATE INDEX products_category_index ON products (category);
CREATE INDEX products_club_id_index ON products (club_id);
CREATE INDEX products_club_id_name_index ON products (club_id, name);
CREATE INDEX products_club_category_fk ON products (club_id, product_category_id);
COMMENT ON COLUMN products.price IS 'Тиыны (в MySQL decimal(12,2) в тенге)';

-- 2026_08_08_072344_create_stock_movements_table (+ club_id, составные FK, индекс)
CREATE TABLE stock_movements (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id    bigint NOT NULL,
    user_id       bigint,
    type          varchar(255) NOT NULL,
    quantity      bigint NOT NULL CHECK (quantity >= 0),
    balance_after bigint NOT NULL CHECK (balance_after >= 0),
    note          varchar(255),
    created_at    timestamptz,
    updated_at    timestamptz,
    club_id       bigint NOT NULL,
    CONSTRAINT stock_movements_type_check CHECK (type IN ('receipt', 'write_off')),
    CONSTRAINT stock_movements_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT stock_movements_club_product_fk FOREIGN KEY (club_id, product_id)
        REFERENCES products (club_id, id) ON DELETE CASCADE,
    CONSTRAINT stock_movements_club_user_fk FOREIGN KEY (club_id, user_id)
        REFERENCES club_memberships (club_id, user_id)
);
CREATE INDEX stock_movements_type_index ON stock_movements (type);
CREATE INDEX stock_movements_product_id_created_at_index ON stock_movements (product_id, created_at);
CREATE INDEX stock_movements_club_id_index ON stock_movements (club_id);
CREATE INDEX stock_movements_club_id_created_at_index ON stock_movements (club_id, created_at);
CREATE INDEX stock_movements_club_product_fk ON stock_movements (club_id, product_id);
CREATE INDEX stock_movements_club_user_fk ON stock_movements (club_id, user_id);

-- 2026_08_08_082028_create_cash_shifts_table (+ club_id, составные FK)
CREATE TABLE cash_shifts (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    opened_by       bigint,
    closed_by       bigint,
    status          varchar(255) NOT NULL,
    open_marker     boolean,
    opening_balance bigint NOT NULL,
    closing_balance bigint,
    opened_at       timestamptz NOT NULL,
    closed_at       timestamptz,
    created_at      timestamptz,
    updated_at      timestamptz,
    club_id         bigint NOT NULL,
    CONSTRAINT cash_shifts_status_check CHECK (status IN ('open', 'closed')),
    CONSTRAINT cash_shifts_club_id_open_marker_unique UNIQUE (club_id, open_marker),
    CONSTRAINT cash_shifts_club_id_id_unique UNIQUE (club_id, id),
    CONSTRAINT cash_shifts_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT cash_shifts_opened_by_membership_fk FOREIGN KEY (club_id, opened_by)
        REFERENCES club_memberships (club_id, user_id),
    CONSTRAINT cash_shifts_closed_by_membership_fk FOREIGN KEY (club_id, closed_by)
        REFERENCES club_memberships (club_id, user_id)
);
CREATE INDEX cash_shifts_status_index ON cash_shifts (status);
CREATE INDEX cash_shifts_club_id_index ON cash_shifts (club_id);
CREATE INDEX cash_shifts_opened_by_membership_fk ON cash_shifts (club_id, opened_by);
CREATE INDEX cash_shifts_closed_by_membership_fk ON cash_shifts (club_id, closed_by);
COMMENT ON COLUMN cash_shifts.open_marker IS 'true у открытой смены, NULL у закрытой: UNIQUE (club_id, open_marker) = одна открытая смена на клуб';
COMMENT ON COLUMN cash_shifts.opening_balance IS 'Тиыны (в MySQL decimal(14,2) в тенге)';
COMMENT ON COLUMN cash_shifts.closing_balance IS 'Тиыны (в MySQL decimal(14,2) в тенге)';

-- 2026_08_08_082029_create_cash_transactions_table, receipt_data (120000), club_id, составные FK,
-- индекс (125224), refund_of_id (2026_10_24_100000).
CREATE TABLE cash_transactions (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cash_shift_id bigint NOT NULL,
    refund_of_id  bigint,
    user_id       bigint,
    type          varchar(255) NOT NULL,
    amount        bigint NOT NULL,
    description   varchar(255) NOT NULL,
    receipt_data  jsonb,
    created_at    timestamptz,
    updated_at    timestamptz,
    club_id       bigint NOT NULL,
    CONSTRAINT cash_transactions_type_check CHECK (type IN ('income', 'expense')),
    CONSTRAINT cash_transactions_refund_of_id_unique UNIQUE (refund_of_id),
    CONSTRAINT cash_transactions_refund_of_id_foreign FOREIGN KEY (refund_of_id)
        REFERENCES cash_transactions (id) ON DELETE SET NULL,
    CONSTRAINT cash_transactions_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT cash_transactions_club_shift_fk FOREIGN KEY (club_id, cash_shift_id)
        REFERENCES cash_shifts (club_id, id) ON DELETE CASCADE,
    CONSTRAINT cash_transactions_club_user_fk FOREIGN KEY (club_id, user_id)
        REFERENCES club_memberships (club_id, user_id)
);
CREATE INDEX cash_transactions_type_index ON cash_transactions (type);
CREATE INDEX cash_transactions_club_id_index ON cash_transactions (club_id);
CREATE INDEX cash_transactions_club_id_created_at_index ON cash_transactions (club_id, created_at);
CREATE INDEX cash_transactions_club_shift_fk ON cash_transactions (club_id, cash_shift_id);
CREATE INDEX cash_transactions_club_user_fk ON cash_transactions (club_id, user_id);
COMMENT ON COLUMN cash_transactions.amount IS 'Тиыны (в MySQL decimal(14,2) в тенге)';
COMMENT ON COLUMN cash_transactions.description IS 'Маркер «Продажа POS» (CashTransaction::POS_SALE) не переводится';
COMMENT ON COLUMN cash_transactions.receipt_data IS '{items:[…]} для продажи POS или {top_up:{user_id,balance_type,bonus}}; суммы внутри — тенге (число), см. open-questions';

-- 2026_11_02_100000_create_club_services_table
CREATE TABLE club_services (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id    bigint NOT NULL,
    name       varchar(150) NOT NULL,
    price      bigint NOT NULL,
    unit       varchar(30),
    is_active  boolean NOT NULL DEFAULT true,
    created_at timestamptz,
    updated_at timestamptz,
    CONSTRAINT club_services_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE
);
CREATE INDEX club_services_club_id_is_active_name_index ON club_services (club_id, is_active, name);
COMMENT ON COLUMN club_services.price IS 'Тиыны (в MySQL decimal(12,2) в тенге)';

-- ---------------------------------------------------------------------------
-- Зоны, ПК, тарифы
