-- 2026_08_08_103410_create_club_zones_table, layout (104240), rotation (2026_10_10_123811),
-- club_id, price_per_hour (2026_10_15_170000).
CREATE TABLE club_zones (
    id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name           varchar(255) NOT NULL,
    description    varchar(255),
    capacity       bigint CHECK (capacity >= 0),
    price_per_hour bigint,
    icon           varchar(40) NOT NULL DEFAULT 'desktop',
    theme          varchar(20) NOT NULL DEFAULT 'neutral',
    status         varchar(20) NOT NULL DEFAULT 'available',
    is_featured    boolean NOT NULL DEFAULT false,
    sort_order     bigint NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
    position_x     bigint NOT NULL DEFAULT 20 CHECK (position_x >= 0),
    position_y     bigint NOT NULL DEFAULT 20 CHECK (position_y >= 0),
    width          bigint NOT NULL DEFAULT 320 CHECK (width >= 0),
    height         bigint NOT NULL DEFAULT 180 CHECK (height >= 0),
    rotation       smallint NOT NULL DEFAULT 0 CHECK (rotation >= 0),
    created_at     timestamptz,
    updated_at     timestamptz,
    club_id        bigint NOT NULL,
    CONSTRAINT club_zones_icon_check CHECK (icon IN ('crown', 'desktop', 'gamepad', 'mug-hot', 'couch', 'dice', 'door-open', 'bong', 'smoking')),
    CONSTRAINT club_zones_theme_check CHECK (theme IN ('green', 'neutral', 'yellow', 'purple', 'blue')),
    CONSTRAINT club_zones_status_check CHECK (status IN ('available', 'busy', 'service')),
    CONSTRAINT club_zones_club_id_id_unique UNIQUE (club_id, id),
    CONSTRAINT club_zones_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE
);
CREATE INDEX club_zones_status_index ON club_zones (status);
CREATE INDEX club_zones_sort_order_index ON club_zones (sort_order);
CREATE INDEX club_zones_club_id_index ON club_zones (club_id);
COMMENT ON COLUMN club_zones.price_per_hour IS 'Тиыны (в MySQL decimal(12,2) в тенге); NULL — поминутной покупки в зоне нет';

-- 2026_08_08_111611_create_club_computers_table и 20 миграций добавления полей
-- (last_seen_at, is_reserved, club_id, agent identity, hardware, display_name, session_ends_at,
-- current_session_user_id, agent_token, staff visit, session_guest, mac unique, agent update,
-- power commands, staff_message).
CREATE TABLE club_computers (
    id                      bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_zone_id            bigint NOT NULL,
    number                  bigint NOT NULL CHECK (number >= 0),
    status                  varchar(20) NOT NULL DEFAULT 'available',
    power_command           varchar(16),
    power_command_at        timestamptz,
    wake_requested_at       timestamptz,
    is_reserved             boolean NOT NULL DEFAULT false,
    position_x              bigint NOT NULL DEFAULT 5 CHECK (position_x >= 0),
    position_y              bigint NOT NULL DEFAULT 5 CHECK (position_y >= 0),
    created_at              timestamptz,
    updated_at              timestamptz,
    last_seen_at            timestamptz,
    club_id                 bigint NOT NULL,
    device_name             varchar(255),
    display_name            varchar(255),
    device_id               varchar(255),
    agent_state             varchar(20),
    agent_version           varchar(50),
    agent_update_version    varchar(20),
    agent_update_offers     smallint NOT NULL DEFAULT 0 CHECK (agent_update_offers >= 0),
    agent_update_offered_at timestamptz,
    current_session_id      varchar(255),
    current_session_user_id bigint,
    session_guest           boolean NOT NULL DEFAULT false,
    session_ends_at         timestamptz,
    staff_user_id           bigint,
    staff_kind              varchar(16),
    staff_until             timestamptz,
    mac_address             varchar(17),
    local_ip                varchar(45),
    remote_ip               varchar(45),
    cpu_model               varchar(255),
    cpu_cores               integer CHECK (cpu_cores >= 0),
    ram_total_mb            bigint CHECK (ram_total_mb >= 0),
    gpu_model               varchar(255),
    os_version              varchar(255),
    hardware_reported_at    timestamptz,
    agent_token_hash        varchar(64),
    agent_token_issued_at   timestamptz,
    staff_message           varchar(300),
    staff_message_at        timestamptz,
    CONSTRAINT club_computers_status_check CHECK (status IN ('available', 'online', 'offline', 'restarting')),
    CONSTRAINT club_computers_power_command_check CHECK (power_command IN ('restart', 'shutdown', 'service')),
    CONSTRAINT club_computers_agent_state_check CHECK (agent_state IN ('idle', 'in_session', 'locked', 'shutting_down')),
    CONSTRAINT club_computers_staff_kind_check CHECK (staff_kind IN ('pin', 'panel', 'signin')),
    CONSTRAINT club_computers_club_zone_id_number_unique UNIQUE (club_zone_id, number),
    CONSTRAINT club_computers_club_id_id_unique UNIQUE (club_id, id),
    CONSTRAINT club_computers_club_device_id_unique UNIQUE (club_id, device_id),
    CONSTRAINT club_computers_club_mac_unique UNIQUE (club_id, mac_address),
    CONSTRAINT club_computers_agent_token_hash_unique UNIQUE (agent_token_hash),
    CONSTRAINT club_computers_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT club_computers_club_zone_fk FOREIGN KEY (club_id, club_zone_id)
        REFERENCES club_zones (club_id, id) ON DELETE CASCADE,
    CONSTRAINT club_computers_current_session_user_id_foreign FOREIGN KEY (current_session_user_id)
        REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT club_computers_staff_user_id_foreign FOREIGN KEY (staff_user_id)
        REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX club_computers_status_index ON club_computers (status);
CREATE INDEX club_computers_last_seen_at_index ON club_computers (last_seen_at);
CREATE INDEX club_computers_club_id_index ON club_computers (club_id);
CREATE INDEX club_computers_club_device_name_index ON club_computers (club_id, device_name);
CREATE INDEX club_computers_club_id_wake_requested_at_index ON club_computers (club_id, wake_requested_at);
CREATE INDEX club_computers_club_zone_fk ON club_computers (club_id, club_zone_id);
CREATE INDEX club_computers_current_session_user_id_foreign ON club_computers (current_session_user_id);
CREATE INDEX club_computers_staff_user_id_foreign ON club_computers (staff_user_id);
COMMENT ON COLUMN club_computers.last_seen_at IS 'Heartbeat. В новом стеке онлайн-статус живёт в Valkey, в БД — только смена состояния (docs/schema-changes.md)';

-- 2026_10_10_130455_create_tariffs_table, subscription options (131809), club_id,
-- sale_periods (2026_10_25/26), color/club_name удалены (2026_10_28), deleted_at (2026_10_29).
CREATE TABLE tariffs (
    id                     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name                   varchar(100) NOT NULL,
    description            text,
    duration_minutes       bigint NOT NULL CHECK (duration_minutes >= 0),
    price                  bigint NOT NULL,
    is_active              boolean NOT NULL DEFAULT true,
    created_at             timestamptz,
    updated_at             timestamptz,
    payment_method         varchar(32) NOT NULL DEFAULT 'main_balance_only',
    currency               varchar(10) NOT NULL DEFAULT 'KZT',
    discount_enabled       boolean NOT NULL DEFAULT false,
    user_roles             jsonb,
    usage_limit_enabled    boolean NOT NULL DEFAULT false,
    usage_limit_minutes    bigint CHECK (usage_limit_minutes >= 0),
    quantity_limit_enabled boolean NOT NULL DEFAULT false,
    quantity_limit         bigint CHECK (quantity_limit >= 0),
    validity_periods       jsonb,
    sale_periods           jsonb,
    club_id                bigint NOT NULL,
    deleted_at             timestamptz,
    CONSTRAINT tariffs_payment_method_check CHECK (payment_method IN ('main_balance_only', 'main_or_bonus')),
    CONSTRAINT tariffs_club_id_name_unique UNIQUE (club_id, name),
    CONSTRAINT tariffs_club_id_id_unique UNIQUE (club_id, id),
    CONSTRAINT tariffs_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE
);
CREATE INDEX tariffs_duration_minutes_index ON tariffs (duration_minutes);
CREATE INDEX tariffs_is_active_index ON tariffs (is_active);
CREATE INDEX tariffs_club_id_index ON tariffs (club_id);
COMMENT ON COLUMN tariffs.price IS 'Тиыны (в MySQL decimal(12,2) в тенге)';
COMMENT ON COLUMN tariffs.validity_periods IS '[{start_day,start_time,end_day,end_time}], дни mon..sun, время HH:MM (WeeklyPeriods)';
COMMENT ON COLUMN tariffs.sale_periods IS 'Как validity_periods; NULL — продаётся всегда';

-- 2026_10_10_131118_create_club_zone_tariff_table (+ club_id, составные FK)
CREATE TABLE club_zone_tariff (
    club_zone_id bigint NOT NULL,
    tariff_id    bigint NOT NULL,
    club_id      bigint NOT NULL,
    CONSTRAINT club_zone_tariff_pkey PRIMARY KEY (club_zone_id, tariff_id),
    CONSTRAINT club_zone_tariff_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT club_zone_tariff_club_zone_fk FOREIGN KEY (club_id, club_zone_id)
        REFERENCES club_zones (club_id, id) ON DELETE CASCADE,
    CONSTRAINT club_zone_tariff_tariff_fk FOREIGN KEY (club_id, tariff_id)
        REFERENCES tariffs (club_id, id) ON DELETE CASCADE
);
CREATE INDEX club_zone_tariff_club_id_index ON club_zone_tariff (club_id);
CREATE INDEX club_zone_tariff_club_zone_fk ON club_zone_tariff (club_id, club_zone_id);
CREATE INDEX club_zone_tariff_tariff_fk ON club_zone_tariff (club_id, tariff_id);

