-- 2026_10_19_100000_create_session_purchases_and_time_packages
CREATE TABLE session_purchases (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id     bigint NOT NULL,
    session_id  varchar(36) NOT NULL,
    user_id     bigint NOT NULL,
    kind        varchar(10) NOT NULL,
    tariff_id   bigint,
    name        varchar(255) NOT NULL,
    minutes     bigint NOT NULL CHECK (minutes >= 0),
    main_cents  bigint NOT NULL DEFAULT 0 CHECK (main_cents >= 0),
    bonus_cents bigint NOT NULL DEFAULT 0 CHECK (bonus_cents >= 0),
    expires_at  timestamptz,
    created_at  timestamptz,
    updated_at  timestamptz,
    CONSTRAINT session_purchases_kind_check CHECK (kind IN ('tariff', 'minutes')),
    CONSTRAINT session_purchases_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT session_purchases_user_id_foreign FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT session_purchases_tariff_id_foreign FOREIGN KEY (tariff_id) REFERENCES tariffs (id) ON DELETE SET NULL
);
CREATE INDEX session_purchases_club_id_session_id_index ON session_purchases (club_id, session_id);
CREATE INDEX session_purchases_created_at_index ON session_purchases (created_at);
CREATE INDEX session_purchases_user_id_foreign ON session_purchases (user_id);
CREATE INDEX session_purchases_tariff_id_foreign ON session_purchases (tariff_id);
COMMENT ON COLUMN session_purchases.main_cents IS 'Тиыны (уже в MySQL)';
COMMENT ON COLUMN session_purchases.bonus_cents IS 'Тиыны (уже в MySQL)';

CREATE TABLE time_packages (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id      bigint NOT NULL,
    user_id      bigint NOT NULL,
    tariff_id    bigint,
    name         varchar(255) NOT NULL,
    minutes_left bigint NOT NULL CHECK (minutes_left >= 0),
    expires_at   timestamptz NOT NULL,
    created_at   timestamptz,
    updated_at   timestamptz,
    CONSTRAINT time_packages_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT time_packages_user_id_foreign FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT time_packages_tariff_id_foreign FOREIGN KEY (tariff_id) REFERENCES tariffs (id) ON DELETE SET NULL
);
CREATE INDEX time_packages_club_id_user_id_expires_at_index ON time_packages (club_id, user_id, expires_at);
CREATE INDEX time_packages_user_id_foreign ON time_packages (user_id);
CREATE INDEX time_packages_tariff_id_foreign ON time_packages (tariff_id);

-- 2026_10_15_130000_create_computer_reservations_table
CREATE TABLE computer_reservations (
