CREATE INDEX computer_reservations_club_computer_fk ON computer_reservations (club_id, club_computer_id);
CREATE INDEX computer_reservations_user_id_foreign ON computer_reservations (user_id);
CREATE INDEX computer_reservations_created_by_foreign ON computer_reservations (created_by);

