COMMENT ON COLUMN transfer_codes.amount_cents IS 'Тиыны (уже в MySQL)';

-- 2026_10_16_100000_create_chat_messages_table
CREATE TABLE chat_messages (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id          bigint NOT NULL,
