    updated_at       timestamptz,
    CONSTRAINT chat_messages_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT chat_messages_customer_id_foreign FOREIGN KEY (customer_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT chat_messages_author_id_foreign FOREIGN KEY (author_id) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT chat_messages_club_computer_id_foreign FOREIGN KEY (club_computer_id)
        REFERENCES club_computers (id) ON DELETE SET NULL
);
CREATE INDEX chat_messages_club_id_customer_id_id_index ON chat_messages (club_id, customer_id, id);
CREATE INDEX chat_messages_club_id_from_staff_read_at_index ON chat_messages (club_id, from_staff, read_at);
CREATE INDEX chat_messages_customer_id_foreign ON chat_messages (customer_id);
CREATE INDEX chat_messages_author_id_foreign ON chat_messages (author_id);
CREATE INDEX chat_messages_club_computer_id_foreign ON chat_messages (club_computer_id);

-- 2026_10_17_120000_create_shop_orders_table
CREATE TABLE shop_orders (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id          bigint NOT NULL,
    user_id          bigint NOT NULL,
    club_computer_id bigint,
    computer_name    varchar(255),
    items            jsonb NOT NULL,
    amount           bigint NOT NULL,
    status           varchar(20) NOT NULL DEFAULT 'new',
    handled_by       bigint,
    handled_at       timestamptz,
    created_at       timestamptz,
    updated_at       timestamptz,
    CONSTRAINT shop_orders_status_check CHECK (status IN ('new', 'done', 'cancelled')),
    CONSTRAINT shop_orders_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT shop_orders_user_id_foreign FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT shop_orders_club_computer_id_foreign FOREIGN KEY (club_computer_id)
        REFERENCES club_computers (id) ON DELETE SET NULL,
    CONSTRAINT shop_orders_handled_by_foreign FOREIGN KEY (handled_by) REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX shop_orders_club_id_status_id_index ON shop_orders (club_id, status, id);
CREATE INDEX shop_orders_club_id_id_index ON shop_orders (club_id, id);
CREATE INDEX shop_orders_user_id_foreign ON shop_orders (user_id);
CREATE INDEX shop_orders_club_computer_id_foreign ON shop_orders (club_computer_id);
CREATE INDEX shop_orders_handled_by_foreign ON shop_orders (handled_by);
COMMENT ON COLUMN shop_orders.amount IS 'Тиыны (в MySQL decimal(12,2) в тенге)';

-- 2026_10_18_120000_telegram_gateway_password_recovery
CREATE TABLE password_recovery_codes (
