CREATE INDEX todo_tasks_created_by_foreign ON todo_tasks (created_by);
CREATE INDEX todo_tasks_done_by_foreign ON todo_tasks (done_by);
COMMENT ON COLUMN todo_tasks.due_on IS 'Календарный день клуба (не момент времени)';

