-- 2026_10_10_143524_create_activity_logs_table, club_id, составной FK, индексы (125224, 150000),
-- user_id и ip_address NOT NULL (2026_10_13_171650).
CREATE TABLE activity_logs (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event        varchar(60) NOT NULL,
    description  text NOT NULL,
    user_id      bigint NOT NULL,
    subject_type varchar(100),
    subject_id   bigint CHECK (subject_id >= 0),
    details      jsonb,
    ip_address   varchar(45) NOT NULL,
    user_agent   text,
    created_at   timestamptz,
    updated_at   timestamptz,
    club_id      bigint NOT NULL,
    CONSTRAINT activity_logs_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT activity_logs_club_user_fk FOREIGN KEY (club_id, user_id)
        REFERENCES club_memberships (club_id, user_id)
);
CREATE INDEX activity_logs_event_index ON activity_logs (event);
CREATE INDEX activity_logs_created_at_event_index ON activity_logs (created_at, event);
CREATE INDEX activity_logs_subject_type_subject_id_index ON activity_logs (subject_type, subject_id);
CREATE INDEX activity_logs_club_id_index ON activity_logs (club_id);
CREATE INDEX activity_logs_club_id_created_at_index ON activity_logs (club_id, created_at);
CREATE INDEX activity_logs_club_id_event_created_at_index ON activity_logs (club_id, event, created_at);
CREATE INDEX activity_logs_club_user_fk ON activity_logs (club_id, user_id);
COMMENT ON COLUMN activity_logs.subject_type IS 'Имя класса Eloquent (App\Models\…), морф-связь';
COMMENT ON COLUMN activity_logs.details IS 'Суммы внутри — тенге (строка/число), не тиыны';

-- 2026_10_15_100000_create_superadmin_cabinet
CREATE TABLE platform_logs (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      bigint,
    club_id      bigint,
    event        varchar(64) NOT NULL,
    description  varchar(500) NOT NULL,
    subject_type varchar(255),
    subject_id   bigint CHECK (subject_id >= 0),
    details      jsonb,
    ip_address   varchar(45) NOT NULL,
    user_agent   varchar(500),
    created_at   timestamptz,
    updated_at   timestamptz,
    CONSTRAINT platform_logs_user_id_foreign FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT platform_logs_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE SET NULL
);
CREATE INDEX platform_logs_subject_type_subject_id_index ON platform_logs (subject_type, subject_id);
CREATE INDEX platform_logs_created_at_index ON platform_logs (created_at);
CREATE INDEX platform_logs_club_id_created_at_index ON platform_logs (club_id, created_at);
CREATE INDEX platform_logs_user_id_foreign ON platform_logs (user_id);

-- 2026_10_15_120000_create_platform_settings_table
CREATE TABLE platform_settings (
    key        varchar(64) PRIMARY KEY,
    value      jsonb,
    updated_by bigint,
    created_at timestamptz,
    updated_at timestamptz,
    CONSTRAINT platform_settings_updated_by_foreign FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX platform_settings_updated_by_foreign ON platform_settings (updated_by);

-- ---------------------------------------------------------------------------
-- Локализация
-- ---------------------------------------------------------------------------

-- 2026_10_13_181908_create_languages_and_translations_tables
CREATE TABLE languages (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code       varchar(16) NOT NULL,
    name       varchar(64) NOT NULL,
    is_enabled boolean NOT NULL DEFAULT true,
    is_system  boolean NOT NULL DEFAULT false,
    sort_order integer NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
    created_at timestamptz,
    updated_at timestamptz,
    CONSTRAINT languages_code_unique UNIQUE (code)
);

CREATE TABLE translations (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    language_id bigint NOT NULL,
    "group"     varchar(64) NOT NULL DEFAULT '*',
    key         text NOT NULL,
    key_hash    varchar(40) NOT NULL,
    value       text NOT NULL,
    created_at  timestamptz,
    updated_at  timestamptz,
    CONSTRAINT translations_language_id_group_key_hash_unique UNIQUE (language_id, "group", key_hash),
    CONSTRAINT translations_language_id_foreign FOREIGN KEY (language_id) REFERENCES languages (id) ON DELETE CASCADE
);
COMMENT ON COLUMN translations.key_hash IS 'sha1(group|key), Translation::hashKey()';

-- ---------------------------------------------------------------------------
-- Интеграционный API v1 и вебхуки (2026_10_13_190912_create_integration_api_tables)
-- ---------------------------------------------------------------------------

CREATE TABLE api_keys (
    id                    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id               bigint NOT NULL,
    created_by            bigint NOT NULL,
    name                  varchar(100) NOT NULL,
    prefix                varchar(16) NOT NULL,
    key_hash              varchar(64) NOT NULL,
    scopes                jsonb NOT NULL,
    allowed_ips           jsonb,
    rate_limit_per_minute integer CHECK (rate_limit_per_minute >= 0),
    expires_at            timestamptz,
    last_used_at          timestamptz,
    last_used_ip          varchar(45),
    revoked_at            timestamptz,
    revoked_by            bigint,
    rotated_from_id       bigint,
    created_at            timestamptz,
    updated_at            timestamptz,
    CONSTRAINT api_keys_prefix_unique UNIQUE (prefix),
    CONSTRAINT api_keys_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT api_keys_created_by_foreign FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT api_keys_revoked_by_foreign FOREIGN KEY (revoked_by) REFERENCES users (id),
    CONSTRAINT api_keys_rotated_from_id_foreign FOREIGN KEY (rotated_from_id) REFERENCES api_keys (id) ON DELETE SET NULL
);
CREATE INDEX api_keys_club_id_revoked_at_index ON api_keys (club_id, revoked_at);
CREATE INDEX api_keys_created_by_foreign ON api_keys (created_by);
CREATE INDEX api_keys_revoked_by_foreign ON api_keys (revoked_by);
CREATE INDEX api_keys_rotated_from_id_foreign ON api_keys (rotated_from_id);

CREATE TABLE api_request_logs (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id     bigint,
    api_key_id  bigint,
    key_prefix  varchar(16),
    method      varchar(8) NOT NULL,
    endpoint    varchar(191) NOT NULL,
    status      integer NOT NULL CHECK (status >= 0),
    duration_ms bigint NOT NULL CHECK (duration_ms >= 0),
    ip          varchar(45) NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX api_request_logs_club_id_created_at_index ON api_request_logs (club_id, created_at);
CREATE INDEX api_request_logs_api_key_id_created_at_index ON api_request_logs (api_key_id, created_at);
CREATE INDEX api_request_logs_created_at_index ON api_request_logs (created_at);

CREATE TABLE api_idempotency_keys (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    api_key_id      bigint NOT NULL,
    idempotency_key varchar(100) NOT NULL,
    request_hash    varchar(64) NOT NULL,
    status          integer CHECK (status >= 0),
    response        text,
    created_at      timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT api_idempotency_keys_api_key_id_idempotency_key_unique UNIQUE (api_key_id, idempotency_key),
    CONSTRAINT api_idempotency_keys_api_key_id_foreign FOREIGN KEY (api_key_id) REFERENCES api_keys (id) ON DELETE CASCADE
);
CREATE INDEX api_idempotency_keys_created_at_index ON api_idempotency_keys (created_at);

CREATE TABLE webhook_endpoints (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id         bigint NOT NULL,
    created_by      bigint NOT NULL,
    url             varchar(500) NOT NULL,
    secret          text NOT NULL,
    events          jsonb NOT NULL,
    is_active       boolean NOT NULL DEFAULT true,
    failure_count   bigint NOT NULL DEFAULT 0 CHECK (failure_count >= 0),
    last_success_at timestamptz,
    last_failure_at timestamptz,
    created_at      timestamptz,
    updated_at      timestamptz,
    CONSTRAINT webhook_endpoints_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT webhook_endpoints_created_by_foreign FOREIGN KEY (created_by) REFERENCES users (id)
);
CREATE INDEX webhook_endpoints_club_id_is_active_index ON webhook_endpoints (club_id, is_active);
CREATE INDEX webhook_endpoints_created_by_foreign ON webhook_endpoints (created_by);
COMMENT ON COLUMN webhook_endpoints.secret IS 'В Laravel зашифрован Crypt (APP_KEY), см. docs/open-questions/database.md';

CREATE TABLE webhook_deliveries (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id             bigint NOT NULL,
    webhook_endpoint_id bigint NOT NULL,
    event_id            uuid NOT NULL,
    event               varchar(64) NOT NULL,
    payload             jsonb NOT NULL,
    status              varchar(16) NOT NULL DEFAULT 'pending',
    attempts            integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    last_status_code    integer CHECK (last_status_code >= 0),
    last_error          varchar(255),
    next_attempt_at     timestamptz,
    delivered_at        timestamptz,
    created_at          timestamptz,
    updated_at          timestamptz,
    CONSTRAINT webhook_deliveries_status_check CHECK (status IN ('pending', 'delivered', 'failed', 'skipped')),
    CONSTRAINT webhook_deliveries_event_id_unique UNIQUE (event_id),
    CONSTRAINT webhook_deliveries_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE,
    CONSTRAINT webhook_deliveries_webhook_endpoint_id_foreign FOREIGN KEY (webhook_endpoint_id)
        REFERENCES webhook_endpoints (id) ON DELETE CASCADE
);
CREATE INDEX webhook_deliveries_webhook_endpoint_id_created_at_index ON webhook_deliveries (webhook_endpoint_id, created_at);
CREATE INDEX webhook_deliveries_status_next_attempt_at_index ON webhook_deliveries (status, next_attempt_at);
CREATE INDEX webhook_deliveries_club_id_status_created_at_index ON webhook_deliveries (club_id, status, created_at);

-- ---------------------------------------------------------------------------
-- Мониторинг (2026_10_19_150000_create_monitoring_tables, 2026_10_19_170000)
-- ---------------------------------------------------------------------------

CREATE TABLE server_metrics (
    id                   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    minute               bigint NOT NULL CHECK (minute >= 0),
    load_1               numeric(6, 2),
    load_5               numeric(6, 2),
    load_15              numeric(6, 2),
    cpu_count            integer CHECK (cpu_count >= 0),
    memory_total_mb      bigint CHECK (memory_total_mb >= 0),
    memory_used_mb       bigint CHECK (memory_used_mb >= 0),
    disk_total_mb        bigint CHECK (disk_total_mb >= 0),
    disk_used_mb         bigint CHECK (disk_used_mb >= 0),
    uptime_seconds       bigint CHECK (uptime_seconds >= 0),
    database_mb          bigint CHECK (database_mb >= 0),
    queue_pending        bigint NOT NULL DEFAULT 0 CHECK (queue_pending >= 0),
    queue_failed         bigint NOT NULL DEFAULT 0 CHECK (queue_failed >= 0),
    queue_oldest_seconds bigint CHECK (queue_oldest_seconds >= 0),
    CONSTRAINT server_metrics_minute_unique UNIQUE (minute)
);
COMMENT ON COLUMN server_metrics.minute IS 'Unix-время / 60';

CREATE TABLE request_metrics (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    minute      bigint NOT NULL CHECK (minute >= 0),
    channel     varchar(16) NOT NULL,
    requests    bigint NOT NULL CHECK (requests >= 0),
    errors      bigint NOT NULL CHECK (errors >= 0),
    duration_ms bigint NOT NULL CHECK (duration_ms >= 0),
    CONSTRAINT request_metrics_channel_check CHECK (channel IN ('panel', 'agent', 'api', 'guest')),
    CONSTRAINT request_metrics_minute_channel_unique UNIQUE (minute, channel)
);

CREATE TABLE club_request_metrics (
    id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id        bigint NOT NULL,
    minute         bigint NOT NULL CHECK (minute >= 0),
    agent_requests bigint NOT NULL DEFAULT 0 CHECK (agent_requests >= 0),
    api_requests   bigint NOT NULL DEFAULT 0 CHECK (api_requests >= 0),
    panel_requests bigint NOT NULL DEFAULT 0 CHECK (panel_requests >= 0),
    guest_requests bigint NOT NULL DEFAULT 0 CHECK (guest_requests >= 0),
    errors         bigint NOT NULL DEFAULT 0 CHECK (errors >= 0),
    duration_ms    bigint NOT NULL DEFAULT 0 CHECK (duration_ms >= 0),
    CONSTRAINT club_request_metrics_club_id_minute_unique UNIQUE (club_id, minute),
    CONSTRAINT club_request_metrics_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE
);
CREATE INDEX club_request_metrics_minute_index ON club_request_metrics (minute);

CREATE TABLE club_load_snapshots (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id     bigint NOT NULL,
    captured_at timestamptz NOT NULL,
    weekday     smallint NOT NULL CHECK (weekday >= 0),
    hour        smallint NOT NULL CHECK (hour >= 0),
    computers   bigint NOT NULL CHECK (computers >= 0),
    online      bigint NOT NULL CHECK (online >= 0),
    busy        bigint NOT NULL CHECK (busy >= 0),
    CONSTRAINT club_load_snapshots_club_id_foreign FOREIGN KEY (club_id) REFERENCES clubs (id) ON DELETE CASCADE
);
CREATE INDEX club_load_snapshots_club_id_captured_at_index ON club_load_snapshots (club_id, captured_at);
CREATE INDEX club_load_snapshots_captured_at_index ON club_load_snapshots (captured_at);
COMMENT ON COLUMN club_load_snapshots.weekday IS '1 = понедельник, в часовом поясе клуба';

